// Build Report: validate the inputs, then build the report from calculated values only.
const kpi = $('Get KPIs').first().json;
const exceptions = $('Get Exceptions').all().map(item => item.json);

// 1. Required KPI fields must exist and be numbers (Postgres sends them as text)
const kpiFields = [
  'total_orders', 'total_order_value', 'excluded_canceled_orders',
  'eligible_orders', 'on_time_orders', 'late_orders',
  'on_time_pct', 'delay_rate_pct', 'avg_order_to_ship_days',
];
const badKpi = kpiFields.filter(f =>
  kpi[f] === undefined || kpi[f] === null || kpi[f] === '' || Number.isNaN(Number(kpi[f]))
);
if (badKpi.length > 0) {
  throw new Error('KPI validation failed. Missing or non-numeric fields: ' + badKpi.join(', '));
}
const k = {};
kpiFields.forEach(f => { k[f] = Number(kpi[f]); });

// 2. The numbers must agree with each other
const problems = [];
if (k.eligible_orders + k.excluded_canceled_orders !== k.total_orders) {
  problems.push('eligible + excluded does not equal total orders');
}
if (k.on_time_orders + k.late_orders !== k.eligible_orders) {
  problems.push('on-time + late does not equal eligible orders');
}
if (k.eligible_orders <= 0) {
  problems.push('eligible orders must be above zero');
} else {
  const delayCheck = Math.round(10000 * k.late_orders / k.eligible_orders) / 100;
  if (Math.abs(delayCheck - k.delay_rate_pct) > 0.01) {
    problems.push('delay rate does not match late / eligible');
  }
}

// 3. Every exception row needs its fields
const exFields = ['shipping_mode', 'eligible_orders', 'late_orders', 'delay_rate_pct', 'points_above_overall'];
exceptions.forEach((row, i) => {
  const missing = exFields.filter(f => row[f] === undefined || row[f] === null || row[f] === '');
  if (missing.length > 0) {
    problems.push('exception row ' + (i + 1) + ' is missing: ' + missing.join(', '));
  }
});
if (problems.length > 0) {
  throw new Error('Validation failed: ' + problems.join('; '));
}

// 4. Build the report text
const n0 = v => Number(v).toLocaleString('en-US');
const n2 = v => Number(v).toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });

const lines = [
  'KPI REPORT',
  'Generated (UTC): ' + new Date().toISOString(),
  'Sources: analytics.kpi_summary, analytics.exceptions_shipping_mode',
  '',
  'SUMMARY',
  'Total orders: ' + n0(k.total_orders),
  'Total order value: ' + n2(k.total_order_value),
  'Eligible orders: ' + n0(k.eligible_orders) + ' (excludes ' + n0(k.excluded_canceled_orders) + ' canceled orders)',
  'On-time: ' + n0(k.on_time_orders) + ' (' + n2(k.on_time_pct) + '%)',
  'Late: ' + n0(k.late_orders) + ' (' + n2(k.delay_rate_pct) + '%)',
  'Average order-to-ship days: ' + n2(k.avg_order_to_ship_days),
  '',
  'EXCEPTIONS (delay rate above overall ' + n2(k.delay_rate_pct) + '%, at least 500 eligible orders)',
];
if (exceptions.length === 0) {
  lines.push('No exceptions found.');
} else {
  exceptions.forEach(e => {
    lines.push('- ' + e.shipping_mode + ': ' + n0(e.late_orders) + ' late of ' + n0(e.eligible_orders) +
      ' eligible (' + n2(e.delay_rate_pct) + '%, +' + n2(e.points_above_overall) + ' points)');
  });
}

   const report_text = lines.join('\n');
   const esc = s => String(s).replace(/'/g, "''");
   const log_sql = "INSERT INTO analytics.report_log (status, total_orders, eligible_orders, late_orders, delay_rate_pct, exception_count, report_text, ai_status, ai_summary, ai_check_detail) VALUES ('success', "
  + k.total_orders + ", " + k.eligible_orders + ", " + k.late_orders + ", " + k.delay_rate_pct + ", " + exceptions.length + ", '" + esc(report_text) + "', 'skipped', NULL, NULL) RETURNING run_id, run_at, status, ai_status;";

   return [{ json: { validation: 'passed', kpis: k, exceptions, report_text, log_sql } }];

const item = $input.first().json;
let msg = item.error;
if (msg && typeof msg === 'object') msg = msg.message || JSON.stringify(msg);
if (!msg) msg = item.message || JSON.stringify(item);
const esc = s => String(s).replace(/'/g, "''");
const log_sql = "INSERT INTO analytics.report_log (status, report_text) VALUES ('failed', '" + esc(msg) + "') RETURNING run_id, run_at, status;";
return [{ json: { log_sql } }];

const kpiItems = $('Get KPIs').all();
const exceptionItems = $('Get Exceptions').all();
const monthlyItems = $('Get Monthly').all();

const kpis = kpiItems.map(item => item.json);
const exceptions = exceptionItems.map(item => item.json);
const monthly = monthlyItems.map(item => item.json);

// Validate monthly totals against the KPI totals before slicing to latest 7 months.
const monthlyEligible = monthly.reduce(
  (sum, row) => sum + Number(row.eligible_orders || 0),
  0
);

const monthlyLate = monthly.reduce(
  (sum, row) => sum + Number(row.late_orders || 0),
  0
);

const kpiEligible = Number(kpis[0]?.eligible_orders || 0);
const kpiLate = Number(kpis[0]?.late_orders || 0);

if (monthlyEligible !== kpiEligible) {
  throw new Error(
    `Monthly eligible order total does not reconcile with KPI total: ${monthlyEligible} vs ${kpiEligible}`
  );
}

if (monthlyLate !== kpiLate) {
  throw new Error(
    `Monthly late order total does not reconcile with KPI total: ${monthlyLate} vs ${kpiLate}`
  );
}

// Sort chronologically before selecting the latest 7 months.
const sortedMonthly = [...monthly].sort(
  (a, b) => new Date(a.order_month) - new Date(b.order_month)
);

const latest7 = sortedMonthly.slice(-7);

let materialChange = {
  latest_month: null,
  latest_rate: null,
  baseline_rate: null,
  change_points: null,
  flagged: false
};

if (latest7.length >= 2) {
  const latest = latest7[latest7.length - 1];

  const previous6 = latest7.slice(0, -1);

  const baselineRate =
    previous6.reduce(
      (sum, row) => sum + Number(row.delay_rate_pct || 0),
      0
    ) / previous6.length;

  const latestRate = Number(latest.delay_rate_pct || 0);
  const changePoints = latestRate - baselineRate;

  materialChange = {
    latest_month: latest.order_month,
    latest_rate: latestRate,
    baseline_rate: Number(baselineRate.toFixed(2)),
    change_points: Number(changePoints.toFixed(2)),
    flagged: Math.abs(changePoints) >= 2.0
  };
}

return [
  {
    json: {
      kpis,
      exceptions,
      exception_rule:
        'a shipping mode is an exception when its delay rate is above the overall rate and it has at least 500 eligible orders',
      monthly: latest7,
      material_change: materialChange,
      material_change_rule:
        'flagged when the difference between the latest month and the mean of the previous 6 months is at least 2.0 percentage points',
      data_limits:
        'In-Full % and OTIF unavailable (no delivered quantity); supplier KPIs unavailable (no supplier column); cycle time is order-to-ship days (no delivery date); shipping-mode delay patterns unusually uniform and may reflect dataset build, not proven operational findings.'
    }
  }
];

const payload = $('Build AI Input').first().json;
const kpi = payload.kpis[0];

const exceptions = payload.exceptions.length === 0
  ? 'No exceptions found.'
  : payload.exceptions
      .map(
        row =>
          `${row.shipping_mode}: ${row.delay_rate_pct}% delay rate, ${row.eligible_orders} eligible orders, ${row.late_orders} late orders.`
      )
      .join('\n');

const aiText = `1) Executive summary
Overall delay rate is ${kpi.delay_rate_pct}% across ${kpi.eligible_orders} eligible orders.
Late orders total ${kpi.late_orders}.

2) Material changes
The latest month is ${payload.material_change.latest_month}.
The latest delay rate is ${payload.material_change.latest_rate}%.
The previous-six-month baseline is ${payload.material_change.baseline_rate}%.
The change is ${payload.material_change.change_points} percentage points.
The supplied material-change flag is ${payload.material_change.flagged}.

3) Exceptions
${exceptions}

4) Evidence
KPI evidence: kpis.delay_rate_pct, kpis.eligible_orders, kpis.late_orders.
Exception evidence: exceptions.
Monthly evidence: monthly.
Material-change evidence: material_change.
Data limitations: data_limits.

5) Questions for investigation
Review the supplied monthly performance data for further investigation.
Review the documented data limitations before interpreting operational causes.`;

return [
  {
    json: {
      ai_status: 'mock',
      ai_summary: aiText,
      ai_payload: payload
    }
  }
];

// SYNC NOTE: checker logic must match n8n/ai_check.js (tested copy). Change both together.
const NUMBER_PATTERN =
  /(?<![\w.])\+?(?:\d{1,3}(?:,\d{3})+(?:\.\d+)?|\d+(?:\.\d+)?)%?(?!\w|[.,]\d)/g;

function normalizeNumber(value) {
  return Number(String(value).replace(/,/g, "").replace(/%$/, "").replace(/^\+/, ""));
}

function collectAllowedNumbers(payload) {
  const allowed = new Set();
  function walk(value) {
    if (value === null || value === undefined) return;
    if (typeof value === "string") {
      const found = value.match(NUMBER_PATTERN);
      if (found) for (const m of found) allowed.add(normalizeNumber(m));
      return;
    }
    if (typeof value === "number" && Number.isFinite(value)) { allowed.add(value); return; }
    if (Array.isArray(value)) { for (const item of value) walk(item); return; }
    if (typeof value === "object") { for (const item of Object.values(value)) walk(item); }
  }
  walk(payload);
  return allowed;
}

function checkAiOutput(aiText, payload) {
  const problems = [];
  if (typeof aiText !== "string" || !aiText.trim()) {
    return { ok: false, problems: ["AI output is empty."] };
  }
  const requiredHeadings = [
    "1) Executive summary", "2) Material changes", "3) Exceptions",
    "4) Evidence", "5) Questions for investigation"
  ];
  for (const heading of requiredHeadings) {
    if (!aiText.includes(heading)) problems.push(`Missing required section: ${heading}`);
  }
  const allowedNumbers = collectAllowedNumbers(payload);
  for (const rawLine of aiText.split(/\r?\n/)) {
    const cleanedLine = rawLine.replace(/^\s*\d+[.)]\s*/, "");
    const numberMatches = cleanedLine.match(NUMBER_PATTERN);
    if (!numberMatches) continue;
    for (const match of numberMatches) {
      if (!allowedNumbers.has(normalizeNumber(match))) {
        problems.push(`Invented or unsupported number: ${match}`);
      }
    }
  }
  const causalPatterns = [
    /\bbecause\b/i, /\bdue to\b/i, /\bcaused by\b/i, /\bdriven by\b/i,
    /\bas a result of\b/i, /\bleads to\b/i, /\breason is\b/i
  ];
  for (const section of aiText.split(/\r?\n(?=\d+\)\s)/)) {
    if (section.startsWith("5) Questions for investigation")) continue;
    for (const pattern of causalPatterns) {
      if (pattern.test(section)) {
        problems.push(`Unsupported causal language outside Questions section: ${pattern}`);
      }
    }
  }
  return { ok: problems.length === 0, problems };
}

// ---- node logic: an AI-branch error must never block logging ----
const esc = s => String(s).replace(/'/g, "''");
let ai_status, ai_summary, ai_check_detail;
try {
  const input = $input.first().json;
  const result = checkAiOutput(input.ai_summary, input.ai_payload);
  if (result.ok) {
    ai_status = input.ai_status === "mock" ? "mock" : "passed";
    ai_summary = input.ai_summary;
    ai_check_detail = "";
  } else {
    ai_status = "rejected";
    ai_summary = null; // rejected text is NEVER stored
    ai_check_detail = result.problems.join("; ");
  }
} catch (e) {
  ai_status = "skipped";
  ai_summary = null;
  ai_check_detail = "AI branch error: " + e.message;
}

let update_sql = null;
const runId = Number($('Log Run').first().json.run_id);
if (Number.isInteger(runId)) {
  update_sql =
    "UPDATE analytics.report_log SET ai_status = '" + esc(ai_status) + "', ai_summary = " +
    (ai_summary === null ? "NULL" : "'" + esc(ai_summary) + "'") +
    ", ai_check_detail = '" + esc(ai_check_detail) + "' WHERE run_id = " + runId +
    " RETURNING run_id, status, ai_status, ai_check_detail;";
}

return [{ json: { ai_status, ai_summary, ai_check_detail, update_sql } }];
